/**
 * The Detail screen's scrollable body -- everything below the pinned `DetailHeader`
 * (`StockDetailRoute` renders that separately, outside this `LazyColumn`). Section order matches
 * the spec exactly; each section is independently skippable when its own source data is null/
 * empty (every section composable already guards this internally), but this Screen also gates
 * which sections get a `LazyColumn` `item{}` slot at all -- `verticalArrangement.spacedBy` adds a
 * gap around every item regardless of whether it renders anything, so a section that would
 * internally render nothing still needs excluding here to avoid a stray gap.
 */
@Composable
fun StockDetailScreen(
    detail: StockDetail?,
    preview: StockPreview?,
    expandedChipIds: Set<String>,
    expandedNewsIds: Set<String>,
    onToggleChip: (String) -> Unit,
    onToggleNews: (String) -> Unit,
    scaffoldPadding: PaddingValues,
    modifier: Modifier = Modifier
) {
    val paddingLarge = dimensionResource(id = R.dimen.padding_large)
    // 💡 Deliberately more generous than `paddingLarge` (the screen's edge margin) -- sections
    // sitting only 16dp apart read as visually crowded/ambiguous about where one ends and the
    // next begins, especially between two plain (non-card) sections like WatchList and
    // TechnicalRead. This is the gap between sections only, not the screen's edge padding.
    val sectionSpacing = dimensionResource(id = R.dimen.padding_xxlarge)

    LazyColumn(
        modifier = modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.background),
        contentPadding = PaddingValues(
            bottom = scaffoldPadding.calculateBottomPadding() + paddingLarge,
            start = paddingLarge,
            end = paddingLarge
        ),
        verticalArrangement = Arrangement.spacedBy(sectionSpacing)
    ) {
        val setupConfirming = detail?.setupConfirming.orEmpty()
        val setupConflicting = detail?.setupConflicting.orEmpty()
        if (setupConfirming.isNotEmpty() || setupConflicting.isNotEmpty()) {
            item {
                SetupReasoning(
                    technicalSetup = preview?.technicalSetup,
                    setupConfidence = preview?.setupConfidence,
                    setupNetBias = preview?.setupNetBias,
                    setupConfirming = setupConfirming,
                    setupConflicting = setupConflicting
                )
            }
        }

        // Chart space reserved for a future design + spec pass -- see the stock-analysis-ui
        // spec's "Deferred" section. Rendered unconditionally (not data-driven) between
        // SetupReasoning and HeadlineMetricsStrip, matching the Design mockup's layout.
        item {
            androidx.compose.foundation.layout.Spacer(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(dimensionResource(id = R.dimen.stock_detail_chart_reserved_height))
            )
        }

        if (detail?.technicalIndicators != null) {
            item { HeadlineMetricsStrip(indicators = detail.technicalIndicators) }
        }

        if (detail?.levels != null) {
            item { KeyLevels(levels = detail.levels, price = preview?.price) }
        }

        if (!detail?.watchList.isNullOrEmpty()) {
            item { WatchList(items = detail?.watchList) }
        }

        if (detail?.technicalRead != null) {
            item { TechnicalRead(technicalRead = detail.technicalRead) }
        }

        if (!detail?.conditionLabels.isNullOrEmpty()) {
            item {
                SignalConditions(
                    conditionLabels = detail?.conditionLabels,
                    chipsAdded = preview?.chipsAdded.orEmpty(),
                    chipsRemoved = preview?.chipsRemoved.orEmpty(),
                    expandedChipIds = expandedChipIds,
                    onToggleChip = onToggleChip
                )
            }
        }

        val thesis = detail?.executiveThesis
        if (thesis != null && (thesis.whatTheNumbersSay != null || thesis.valuationContext != null || thesis.macroTransmissionVector != null)) {
            item { DeepStudy(thesis = thesis) }
        }

        val hasScenario = detail?.scenarios.orEmpty().any { it.direction?.uppercase() == "BULLISH" || it.direction?.uppercase() == "BEARISH" }
        if (hasScenario) {
            item { Scenarios(scenarios = detail?.scenarios) }
        }

        if (detail?.fundamentals != null) {
            item { Fundamentals(fundamentals = detail.fundamentals) }
        }

        if (!detail?.considerations.isNullOrEmpty()) {
            item { Consider(considerations = detail?.considerations) }
        }

        if (detail?.macro != null) {
            item { Macro(macro = detail.macro) }
        }

        if (!detail?.calls?.open.isNullOrEmpty()) {
            item { ForwardCalls(calls = detail?.calls) }
        }

        val contextVault = detail?.contextVault
        if (contextVault != null && (!contextVault.eventLog.isNullOrEmpty() || contextVault.thirtyDayTrendTimeline != null)) {
            item { EventLog(contextVault = contextVault) }
        }

        if (!detail?.topNewsStream.isNullOrEmpty()) {
            item {
                DirectNews(
                    newsStream = detail?.topNewsStream,
                    expandedNewsIds = expandedNewsIds,
                    onToggleNews = onToggleNews
                )
            }
        }

        if (detail?.notCovered != null) {
            item { NotCoveredFooter(notCovered = detail.notCovered) }
        }
    }
}
